var DIRECTIVES = ['public','private','no-cache','no-store','must-revalidate','proxy-revalidate','immutable','no-transform'];
function parseMaxAge(str){
  if(str===null || str===undefined || str==='') return {value:null, error:'空值'};
  var s=String(str).trim().toLowerCase();
  if(/^\d+$/.test(s)) return {value:parseInt(s,10), error:null};
  var m=s.match(/^(\d+(?:\.\d+)?)\s*(s|sec|m|min|h|hr|d|day|w|week|y|year)s?$/);
  if(!m) return {value:null, error:'无法解析时长: '+str};
  var n=parseFloat(m[1]), u=m[2];
  var mul = {s:1,sec:1,m:60,min:60,h:3600,hr:3600,d:86400,day:86400,w:604800,week:604800,y:31536000,year:31536000}[u];
  return {value: Math.round(n*mul), error:null};
}
function formatAge(sec){
  if(typeof sec!=='number' || sec<0 || !isFinite(sec)) return '-';
  if(sec===0) return '0s';
  var units=[['y',31536000],['w',604800],['d',86400],['h',3600],['m',60],['s',1]];
  var out=[], rest=Math.floor(sec);
  for(var i=0;i<units.length;i++){
    var q=Math.floor(rest/units[i][1]);
    if(q>0){ out.push(q+units[i][0]); rest-=q*units[i][1]; }
    if(out.length===2) break;
  }
  return out.join(' ');
}
function buildHeader(opt){
  opt = opt || {};
  var parts=[], warns=[];
  if(opt.noStore){
    parts.push('no-store');
    if(opt.maxAge) warns.push('no-store 与 max-age 同时出现，max-age 会被忽略');
    return {header:'Cache-Control: no-store', value:'no-store', directives:['no-store'], warnings:warns};
  }
  if(opt.visibility==='private') parts.push('private');
  else if(opt.visibility==='public') parts.push('public');
  if(opt.noCache) parts.push('no-cache');
  if(typeof opt.maxAge==='number' && opt.maxAge>=0) parts.push('max-age='+opt.maxAge);
  if(typeof opt.sMaxAge==='number' && opt.sMaxAge>=0) parts.push('s-maxage='+opt.sMaxAge);
  if(typeof opt.staleWhileRevalidate==='number' && opt.staleWhileRevalidate>0) parts.push('stale-while-revalidate='+opt.staleWhileRevalidate);
  if(typeof opt.staleIfError==='number' && opt.staleIfError>0) parts.push('stale-if-error='+opt.staleIfError);
  if(opt.mustRevalidate) parts.push('must-revalidate');
  if(opt.immutable) parts.push('immutable');
  if(!parts.length) parts.push('no-cache');
  if(opt.visibility==='private' && typeof opt.sMaxAge==='number') warns.push('private 响应不会被共享缓存存储，s-maxage 无效');
  if(opt.immutable && (!opt.maxAge || opt.maxAge < 86400)) warns.push('immutable 通常配合较长 max-age（>=1 天）用于带指纹的静态资源');
  if(opt.noCache && opt.immutable) warns.push('no-cache 与 immutable 语义冲突');
  var v=parts.join(', ');
  return {header:'Cache-Control: '+v, value:v, directives:parts, warnings:warns};
}
function parseHeader(str){
  var out={raw:String(str||''), directives:{}, list:[], unknown:[]};
  var s=out.raw.replace(/^\s*cache-control\s*:\s*/i,'');
  var toks=s.split(',');
  for(var i=0;i<toks.length;i++){
    var t=toks[i].trim();
    if(!t) continue;
    out.list.push(t);
    var eq=t.indexOf('=');
    if(eq>-1){
      var k=t.slice(0,eq).trim().toLowerCase();
      var v=t.slice(eq+1).trim().replace(/^"|"$/g,'');
      out.directives[k]= /^\d+$/.test(v)? parseInt(v,10) : v;
    } else {
      var kk=t.toLowerCase();
      out.directives[kk]=true;
      if(DIRECTIVES.indexOf(kk)===-1) out.unknown.push(kk);
    }
  }
  return out;
}
function freshness(opt){
  opt = opt || {};
  var age = typeof opt.age==='number' ? opt.age : 0;
  var maxAge = typeof opt.maxAge==='number' ? opt.maxAge : null;
  var swr = typeof opt.staleWhileRevalidate==='number' ? opt.staleWhileRevalidate : 0;
  if(maxAge===null) return {state:'unknown', remaining:null, note:'未提供 max-age，缓存需启发式判断或回源校验'};
  var remain = maxAge - age;
  if(remain > 0) return {state:'fresh', remaining:remain, note:'命中缓存，剩余 '+formatAge(remain)};
  if(swr > 0 && (age - maxAge) <= swr)
    return {state:'stale-revalidating', remaining:0, note:'过期但在 stale-while-revalidate 窗口内，先返回旧副本再后台刷新'};
  return {state:'stale', remaining:0, note:'已过期 '+formatAge(age-maxAge)+'，需回源校验'};
}
function preset(kind){
  var P = {
    'static-hashed': {label:'带指纹静态资源', opt:{visibility:'public', maxAge:31536000, immutable:true}},
    'html': {label:'HTML 文档', opt:{visibility:'public', noCache:true, mustRevalidate:true}},
    'api-private': {label:'用户私有 API', opt:{visibility:'private', noCache:true, mustRevalidate:true}},
    'api-cdn': {label:'可共享 API', opt:{visibility:'public', maxAge:60, sMaxAge:300, staleWhileRevalidate:600}},
    'sensitive': {label:'敏感数据', opt:{noStore:true}},
    'image-cdn': {label:'图片 CDN', opt:{visibility:'public', maxAge:604800, sMaxAge:2592000, staleIfError:86400}}
  };
  return P[kind] || null;
}
function etagFor(body, weak){
  var s=String(body||''), h1=0x811c9dc5, h2=0x01000193;
  for(var i=0;i<s.length;i++){
    h1 ^= s.charCodeAt(i); h1 = (h1*16777619)>>>0;
    h2 = ((h2 + s.charCodeAt(i)*(i+1))*2654435761)>>>0;
  }
  var hex = ('00000000'+h1.toString(16)).slice(-8) + ('00000000'+h2.toString(16)).slice(-8);
  return (weak?'W/':'')+'"'+hex+'"';
}
function etagMatch(reqHeader, etag){
  if(!reqHeader) return false;
  if(reqHeader.trim()==='*') return true;
  var want = String(etag||'').replace(/^W\//,'');
  var parts = String(reqHeader).split(',');
  for(var i=0;i<parts.length;i++){
    if(parts[i].trim().replace(/^W\//,'') === want) return true;
  }
  return false;
}
function auditHeader(str){
  var p=parseHeader(str), issues=[];
  var d=p.directives;
  if(d['no-store'] && (d['max-age']!==undefined || d['public'])) issues.push({level:'warn', msg:'no-store 与 max-age/public 同时出现，缓存语义混乱'});
  if(d['private'] && d['public']) issues.push({level:'error', msg:'public 与 private 互斥'});
  if(d['private'] && d['s-maxage']!==undefined) issues.push({level:'warn', msg:'private 下 s-maxage 无效'});
  if(d['immutable'] && (d['max-age']===undefined || d['max-age']<86400)) issues.push({level:'warn', msg:'immutable 应配合长 max-age'});
  if(d['max-age']===undefined && d['no-store']===undefined && d['no-cache']===undefined)
    issues.push({level:'warn', msg:'缺少新鲜度指令，缓存将走启发式过期'});
  if(d['max-age']!==undefined && d['max-age']>31536000) issues.push({level:'warn', msg:'max-age 超过 1 年，RFC 建议不超过 31536000'});
  if(p.unknown.length) issues.push({level:'info', msg:'未识别指令: '+p.unknown.join(', ')});
  var errors=0, warnings=0;
  for(var i=0;i<issues.length;i++){ if(issues[i].level==='error') errors++; else if(issues[i].level==='warn') warnings++; }
  return {parsed:p, issues:issues, errors:errors, warnings:warnings, ok: errors===0 && warnings===0};
}
if (typeof module !== 'undefined' && module.exports) { module.exports = { DIRECTIVES:DIRECTIVES, parseMaxAge:parseMaxAge, formatAge:formatAge, buildHeader:buildHeader, parseHeader:parseHeader, freshness:freshness, preset:preset, etagFor:etagFor, etagMatch:etagMatch, auditHeader:auditHeader }; }
if (typeof window !== 'undefined') { window.HttpCacheForgePure = { DIRECTIVES:DIRECTIVES, parseMaxAge:parseMaxAge, formatAge:formatAge, buildHeader:buildHeader, parseHeader:parseHeader, freshness:freshness, preset:preset, etagFor:etagFor, etagMatch:etagMatch, auditHeader:auditHeader }; }
